typedef enum { OK, ERR_PARSE, ERR_RANGE } status;
typedef struct { status st; union { long value; const char *msg; } u; } result_long;

static result_long ok_long(long v)            { return (result_long){ OK, .u.value = v }; }
static result_long err_long(status s, const char *m) { return (result_long){ s, .u.msg = m }; }

result_long parse_port(const char *s) {
    char *end; long v = strtol(s, &end, 10);
    if (*end != '\0')      return err_long(ERR_PARSE, "not a number");
    if (v < 1 || v > 65535) return err_long(ERR_RANGE, "out of range");
    return ok_long(v);
}
/* callers test .st before touching .u.value */
